package pe.edu.pucp.oceanlink;
import jakarta.servlet.http.*;import java.sql.*;import java.util.*;
public final class ResumenPantallas{
 public static void cargar(HttpServletRequest r,String vista,List<String[]> capacidad)throws SQLException{
  r.setAttribute("estadoRed",Arrays.asList(DetalleDAO.filas("SELECT COALESCE(SUM(condicion_operativa='OPERATIVO'),0),COALESCE(SUM(condicion_operativa='DEGRADADO'),0),COALESCE(SUM(condicion_operativa='EN_MANTENIMIENTO'),0),COALESCE(SUM(condicion_operativa='FUERA_SERVICIO'),0) FROM segmento WHERE estado=1").get(0)));double available=0;long high=0,critical=0;for(String[] c:capacidad)if(c.length>7){try{available+=Double.parseDouble(c[6]);double p=Double.parseDouble(c[7]);if(p>=80&&p<=95)high++;if(p>95)critical++;}catch(NumberFormatException ignored){}}
  List<String[]> counts;
  switch(vista){
   case "incidencias":counts=DetalleDAO.filas("SELECT (SELECT COUNT(*) FROM incidencia WHERE fase NOT IN('CERRADA','RESTAURADA')),(SELECT COUNT(*) FROM incidencia WHERE fase NOT IN('CERRADA','RESTAURADA') AND severidad='CRITICA'),COUNT(DISTINCT v.id_servicio),COUNT(DISTINCT sol.id_cliente) FROM incidencia i JOIN incidencia_segmento x ON x.id_incidencia=i.id_incidencia JOIN servicio_segmento ss ON ss.id_segmento=x.id_segmento JOIN servicio v ON v.id_servicio=ss.id_servicio JOIN solicitud_capacidad sol ON sol.id_solicitud=v.id_solicitud WHERE i.fase NOT IN('CERRADA','RESTAURADA') AND v.estado='ACTIVO'");break;
   case "mantenimientos":counts=DetalleDAO.filas("SELECT (SELECT COUNT(*) FROM mantenimiento WHERE fase='PROGRAMADO'),(SELECT COUNT(*) FROM mantenimiento WHERE fase='EN_PROGRESO'),(SELECT COUNT(DISTINCT ss.id_servicio) FROM mantenimiento m JOIN segmento s ON (s.id_segmento=m.id_segmento OR m.id_estacion IN(s.id_estacion_origen,s.id_estacion_destino)) JOIN servicio_segmento ss ON ss.id_segmento=s.id_segmento WHERE m.fase<>'FINALIZADO'),(SELECT COUNT(*) FROM mantenimiento WHERE fase='FINALIZADO' AND MONTH(fecha_cierre)=MONTH(CURRENT_DATE) AND YEAR(fecha_cierre)=YEAR(CURRENT_DATE))");break;
   case "afectados":counts=DetalleDAO.filas("SELECT COUNT(DISTINCT i.id_incidencia),COUNT(DISTINCT x.id_segmento),COUNT(DISTINCT v.id_servicio),COUNT(DISTINCT sol.id_cliente) FROM incidencia i JOIN incidencia_segmento x ON x.id_incidencia=i.id_incidencia JOIN servicio_segmento ss ON ss.id_segmento=x.id_segmento JOIN servicio v ON v.id_servicio=ss.id_servicio JOIN solicitud_capacidad sol ON sol.id_solicitud=v.id_solicitud WHERE i.fase NOT IN('CERRADA','RESTAURADA') AND v.estado='ACTIVO'");break;
   default:counts=Collections.singletonList(new String[]{Integer.toString(capacidad.size()),Long.toString(high),Long.toString(critical),String.format(Locale.ROOT,"%.1f Tbps",available)});
  }
  if(vista.equals("capacidad")){double sum=0;for(String[] row:capacidad)sum+=Double.parseDouble(row[7]);counts=Collections.singletonList(new String[]{String.format(Locale.ROOT,"%.1f%%",capacidad.isEmpty()?0:sum/capacidad.size()),Long.toString(critical),Long.toString(high),String.format(Locale.ROOT,"%.1f Tbps",available)});}
  if(vista.equals("afectados"))counts=DetalleDAO.filas("SELECT COUNT(*),COUNT(DISTINCT id_cliente),COALESCE(SUM(capacidad),0),COALESCE(SUM(critico),0) FROM (SELECT v.id_servicio,sol.id_cliente,v.capacidad_contratada_tbps capacidad,MAX(i.severidad='CRITICA') critico FROM servicio v JOIN solicitud_capacidad sol ON sol.id_solicitud=v.id_solicitud JOIN servicio_segmento ss ON ss.id_servicio=v.id_servicio JOIN incidencia_segmento x ON x.id_segmento=ss.id_segmento JOIN incidencia i ON i.id_incidencia=x.id_incidencia WHERE v.estado='ACTIVO' AND i.fase NOT IN('CERRADA','RESTAURADA') GROUP BY v.id_servicio,sol.id_cliente,v.capacidad_contratada_tbps) afectados");
  r.setAttribute("resumen",Arrays.asList(counts.get(0)));r.setAttribute("alcances",DetalleDAO.filas("SELECT id_segmento,codigo_segmento FROM segmento ORDER BY id_segmento"));
  if(vista.equals("historicos")){
   r.setAttribute("eventosInc",DetalleDAO.filas("SELECT DATE_FORMAT(i.fecha_deteccion,'%Y-%m-%d'),i.severidad,i.fase,COALESCE((SELECT GROUP_CONCAT(id_segmento) FROM incidencia_segmento x WHERE x.id_incidencia=i.id_incidencia),''),i.codigo_incidencia,COALESCE((SELECT GROUP_CONCAT(DISTINCT ss.id_servicio) FROM incidencia_segmento x JOIN servicio_segmento ss ON ss.id_segmento=x.id_segmento WHERE x.id_incidencia=i.id_incidencia),'') FROM incidencia i ORDER BY i.fecha_deteccion"));
   r.setAttribute("eventosMant",DetalleDAO.filas("SELECT DATE_FORMAT(m.inicio_programado,'%Y-%m-%d'),t.nombre,m.fase,COALESCE(m.id_segmento,0),m.codigo_mantenimiento,COALESCE((SELECT GROUP_CONCAT(DISTINCT ss.id_servicio) FROM segmento z JOIN servicio_segmento ss ON ss.id_segmento=z.id_segmento WHERE z.id_segmento=m.id_segmento OR m.id_estacion IN(z.id_estacion_origen,z.id_estacion_destino)),'') FROM mantenimiento m JOIN tipo_mantenimiento t ON t.id_tipo_mantenimiento=m.id_tipo_mantenimiento ORDER BY m.inicio_programado"));
   r.setAttribute("histInc",Arrays.asList(DetalleDAO.filas("SELECT COUNT(*),COALESCE(SUM(fase='CERRADA'),0),COALESCE(SUM(severidad='CRITICA'),0),(SELECT COUNT(DISTINCT ss.id_servicio) FROM incidencia_segmento x JOIN servicio_segmento ss ON ss.id_segmento=x.id_segmento) FROM incidencia").get(0)));
   r.setAttribute("histMant",Arrays.asList(DetalleDAO.filas("SELECT COUNT(*),COALESCE(SUM(fase='FINALIZADO'),0),COALESCE(SUM(fase='PROGRAMADO'),0),(SELECT COUNT(DISTINCT ss.id_servicio) FROM mantenimiento m JOIN segmento s ON s.id_segmento=m.id_segmento OR m.id_estacion IN(s.id_estacion_origen,s.id_estacion_destino) JOIN servicio_segmento ss ON ss.id_segmento=s.id_segmento) FROM mantenimiento").get(0)));
   r.setAttribute("serie",DetalleDAO.filas("SELECT DATE_FORMAT(fecha,'%Y-%m-%d'),ROUND(AVG(capacidad_utilizada_tbps/capacidad_total_tbps*100),1),id_segmento FROM historial_capacidad_segmento GROUP BY DATE_FORMAT(fecha,'%Y-%m-%d'),id_segmento ORDER BY DATE_FORMAT(fecha,'%Y-%m-%d'),id_segmento"));
  }
 }
}
